import{_ as e,o as r,c as a,a0 as d}from"./chunks/framework.DYAX5gPL.js";const m=JSON.parse('{"title":"Performance Optimization for Vector Data Layers","description":"","frontmatter":{"title":"Performance Optimization for Vector Data Layers"},"headers":[],"relativePath":"en/api/vt-performance.md","filePath":"en/api/vt-performance.md"}'),o={name:"en/api/vt-performance.md"};function n(i,t,l,s,c,p){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="performance-optimization-for-vector-data-layers" tabindex="-1">Performance Optimization for Vector Data Layers <a class="header-anchor" href="#performance-optimization-for-vector-data-layers" aria-label="Permalink to &quot;Performance Optimization for Vector Data Layers&quot;">​</a></h1><p>The vector data layers covered here include the vector tile layer <a href="/en/api/vector-tile-layer.html">VectorTileLayer</a> and the vector layers (<a href="/en/api/point-layer.html">PointLayer</a>, <a href="/en/api/line-string-layer.html">LineStringLayer</a> and <a href="/en/api/polygon-layer.html">PolygonLayer</a>).</p><h2 id="performance-of-style-updates" tabindex="-1">Performance of Style Updates <a class="header-anchor" href="#performance-of-style-updates" aria-label="Permalink to &quot;Performance of Style Updates&quot;">​</a></h2><p>Vector layers built on Web 3D technology construct the graphic data into a 3D data structure commonly called a Mesh, which is then submitted to the Web 3D API for rendering.</p><p>The impact of style updates on performance mainly depends on whether the Mesh update is partial or full.</p><ul><li>A partial update only updates the changed data within the Mesh and does not require rebuilding it.</li><li>A full update requires the Mesh to be rebuilt entirely.</li></ul><p>Therefore, to optimize performance, full Mesh updates should be avoided as much as possible. The following lists the symbol properties that cause a full Mesh update; in performance-sensitive scenarios, avoid updating them frequently. Symbol properties not listed do not cause full Mesh updates.</p><blockquote><p>❗ means a full Mesh update is caused, 🆗 means it is not</p></blockquote><table tabindex="0"><thead><tr><th>Property</th><th>Vector Tile Layers</th><th>Vector Layers</th></tr></thead><tbody><tr><td>markerFile</td><td>❗</td><td>❗</td></tr><tr><td>markerPlacement</td><td>❗</td><td>❗</td></tr><tr><td>markerSpacing</td><td>❗</td><td>❗</td></tr><tr><td>markerHorizontalAlignment</td><td>❗</td><td>🆗</td></tr><tr><td>markerVerticalAlignment</td><td>❗</td><td>🆗</td></tr><tr><td>textName</td><td>❗</td><td>❗</td></tr><tr><td>textFaceName</td><td>❗</td><td>❗</td></tr><tr><td>textPlacement</td><td>❗</td><td>❗</td></tr><tr><td>textSpacing</td><td>❗</td><td>❗</td></tr><tr><td>textHorizontalAlignment</td><td>❗</td><td>🆗</td></tr><tr><td>textVerticalAlignment</td><td>❗</td><td>🆗</td></tr><tr><td>textWrapWidth</td><td>❗</td><td>🆗</td></tr><tr><td>lineJoin</td><td>❗</td><td>❗</td></tr><tr><td>lineCap</td><td>❗</td><td>❗</td></tr><tr><td>linePatternFile</td><td>❗</td><td>❗</td></tr><tr><td>lineDasharray</td><td>🆗</td><td>❗</td></tr><tr><td>polygonPatternFile</td><td>❗</td><td>❗</td></tr><tr><td>topPolygonFill</td><td>🆗</td><td>❗</td></tr><tr><td>bottomPolygonFill</td><td>🆗</td><td>❗</td></tr></tbody></table><blockquote><p>Note: The <code>textStyle</code> and <code>textWeight</code> properties in the old documentation have been removed in the new version of @maptalks/gl-layers (commented out in the 2026 source code) and no longer trigger Mesh rebuilds; <code>topPolygonFill</code> and <code>bottomPolygonFill</code> are properties newly added for the 3D extrusion layer (ExtrudePolygonLayer) (verified in 2026).</p></blockquote><blockquote><p>This document has been cross-checked against the @maptalks/gl-layers 2026 source code (api-notes-vt-gl.md)</p></blockquote>',11)])])}const u=e(o,[["render",n]]);export{m as __pageData,u as default};
